"""Real CSV validation and controlled apply, with fixed fictional inputs."""
from training.lesson_types import Lesson, Step, select_step as choose, action_step as act
from training.csv_fixtures import CSV_FILES

CONTENT={
 "import-item-catalogue":("Import a verified item catalogue","items","The approved practice CSV contains one new TRAIN-MILK item: Training milk cartons, category Training drinks, base unit TRAIN-EACH, minimum 12 and standard cost PHP 75. Download the practice CSV, validate the complete file, then apply it once. Classification is a separate stewardship step; this import adds no stock.","Imported catalogue fields are master data. Quantity and valuation require a separate supported stock transaction; standard cost is not proof of stock already present."),
 "import-supplier-catalogue":("Import verified supplier details","suppliers","The approved practice CSV contains Training Farm Supplies, code TRAIN-FARM, fictional contact farm@example.com and 21-day payment terms. Download it, validate the complete file, then apply it once. This creates no purchase obligation.","Supplier contact and payment terms must be checked before migration. Importing a supplier does not create an order or change physical stock."),
 "reject-invalid-csv":("Keep an invalid migration unapplied","items","The fictional practice CSV deliberately repeats TRAIN-MILK on two rows. Download it and validate it. Read the duplicate-SKU error and leave the entire job invalid and unapplied. Do not create the apparently valid first row separately to bypass review.","Validation checks the complete file. An error means the job must remain unapplied, even when another row looks correct. Correct the source file through the authorized review process."),
 "import-initial-balances":("Establish an initial balance before any movements","opening_balances","This fresh practice database has no posted stock movements. The approved physical starting chicken quantity is {quantity} kg at PHP 200/kg in TRAIN-STORE. Download the opening CSV, validate it, and apply the single starting balance once. This is initialization, not a supplier receipt against a PO.","Opening-balance migration is allowed only before stock movements exist. Its quantities and unit costs must be reconciled to genuine starting evidence."),
 "refuse-duplicate-opening-import":("Protect an existing ledger from a second opening import","opening_balances","This practice already has posted stock history. A second opening CSV would duplicate its starting stock. Download and validate the practice opening file, then try Apply to read the refusal. Leave the job unapplied and the existing ledger unchanged.","A validated file is not authorization to overwrite an existing ledger. Opening-balance apply is blocked after any stock movement; later differences need an authorized correction workflow."),
}
LESSONS=[]
for id,(title,type,situation,concept) in CONTENT.items():
    filename=CSV_FILES[id][0]
    steps=[choose('[aria-label="Migration import type"]',"Choose "+{"items":"Items","suppliers":"Suppliers","opening_balances":"Opening balances"}[type]+".",type),Step('[aria-label="Migration CSV"]',"Download the practice CSV, then choose "+filename+" from your Downloads folder.",filename,"change"),act('[data-training="migration-validate"]',"Validate the complete fictional file and review its result.",f"/migration/imports/{type}/validate")]
    if id=="reject-invalid-csv":steps.append(act('[data-training="migration-errors"]',"Open Review errors and read the duplicate SKU on row 3. Keep the job unapplied."))
    if id!="reject-invalid-csv":steps.append(act('[data-training="migration-apply"]',"Read the existing-ledger refusal and retain the unapplied file." if id=="refuse-duplicate-opening-import" else "Apply the reviewed valid file once; retain its applied job record.","/migration/imports/*/apply",409 if id=="refuse-duplicate-opening-import" else None))
    rule="Use only the approved fictional file in training. Check each validation error and retain the job history; do not use production exports, credentials or real employee details."
    example="A starting 5 kg at PHP 200/kg is PHP 1,000, and must not be imported again after stock history begins." if type=="opening_balances" else "A 21-day payment term is not a 21-day delivery promise; importing a supplier does not receive stock." if type=="suppliers" else "A carton catalogue unit at PHP 75 does not mean 75 cartons exist. A duplicate SKU must be corrected before the complete file is applied."
    question="Should the apparently valid first row be applied while the duplicate SKU error remains? yes or no" if id=="reject-invalid-csv" else "Does validating a file alone apply its records? yes or no"
    LESSONS.append(Lesson(id,"Z",title,("owner",),"/readiness","migration_"+id,situation,concept,example,rule,question,"no",rule+" "+situation,("readiness.py",),tuple(steps),quantity=5,global_access=True))
